 wild=['\U0001fab5 Black woodpecker', '\U0001f985 Northern goshawk', '\U0001f426 Treecreeper', '\U0001f43f\ufe0f Red squirrel', '\U0001f333 Scots pine \u00b7 Larch \u00b7 Pedunculate oak'],
